{
  "model_name": "SMWeinberg_gen",
  "info": {
    "authors": ["B. Fuks", "J. Neundorf", "K. Peters", "R. Ruiz", "M. Saimpert"],
    "version": "1.0",
    "date": "2021"
  },
  "interaction_order_hierarchy": [["QCD", 1], ["QED", 2], ["NP", 1]],
  "feynman_gauge": true,
  "gauge_groups": [],
  "index_decls": [],
  "parameters": [
    {
      "name": "Lambda",
      "parameter_type": "External",
      "value": "200000.",
      "block_name": "NUPHYSICS",
      "order_block": 1,
      "description": "EFT cutoff Lambda [GeV] of the Weinberg operator (eq:dim5Lag); paper benchmark 200 TeV"
    },
    {
      "name": "Cll",
      "parameter_type": "External",
      "indices": ["Generation", "Generation"],
      "block_name": "NUPHYSICS",
      "interaction_order": ["NP", 1],
      "value_rules": [
        {"lhs": "Cll[1,1]", "rhs": "0"},
        {"lhs": "Cll[1,2]", "rhs": "0"},
        {"lhs": "Cll[1,3]", "rhs": "0"},
        {"lhs": "Cll[2,1]", "rhs": "0"},
        {"lhs": "Cll[2,2]", "rhs": "1"},
        {"lhs": "Cll[2,3]", "rhs": "0"},
        {"lhs": "Cll[3,1]", "rhs": "0"},
        {"lhs": "Cll[3,2]", "rhs": "0"},
        {"lhs": "Cll[3,3]", "rhs": "0"}
      ],
      "description": "Wilson coefficient C5^{ll'} of the Weinberg operator (dimensionless), eq:dim5Lag; benchmark C5 = delta_{l,mu} delta_{l',mu} (Les Houches NUPHYSICS 2-7)"
    },
    {
      "name": "mN",
      "parameter_type": "Internal",
      "value": "Abs[Cll[1,1] + Cll[1,2] + Cll[1,3] + Cll[2,2] + Cll[2,3] + Cll[3,3]]*vev^2/Lambda",
      "description": "m_N = |sum_ll' C5| v^2/Lambda (eq:heavyNMass): absorbed 1/Lambda, mass dimension 1, units GeV; benchmark |sum C5|=1 and Lambda=200 TeV give 0.3025 GeV (paper table 0.3 GeV)"
    },
    {
      "name": "wN",
      "parameter_type": "Internal",
      "value": "0.",
      "description": "Gamma_N [GeV], Internal per tab:ufoParams (Les Houches 9900012); the paper gives no dynamical width for the off-shell EFT mediator N, hence 0"
    }
  ],
  "particles": [
    {
      "spin_type": "F",
      "class_index": 100,
      "class_name": "NM",
      "self_conjugate": true,
      "mass": {"sym": "mN", "value": "Internal"},
      "width": {"sym": "wN", "value": "Internal"},
      "pdg": 9900012,
      "particle_name": "N",
      "propagator_label": "N",
      "propagator_type": "Straight",
      "propagator_arrow": "None",
      "full_name": "Majorana neutrino N (Weinberg-operator mediator)"
    }
  ],
  "lagrangian_terms": [
    {
      "name": "LNkin",
      "delayed": true,
      "expression": "Block[{mu}, I/2 NMbar.Ga[mu].del[NM, mu] - 1/2 mN NMbar.NM]"
    },
    {
      "name": "LNW",
      "delayed": true,
      "expression": "Block[{mu, ff}, Sum[-gw/Sqrt[2] W[mu] NMbar.Ga[mu].ProjM.l[ff] + HC[-gw/Sqrt[2] W[mu] NMbar.Ga[mu].ProjM.l[ff]], {ff, 1, 3}]]"
    },
    {
      "name": "LNZ",
      "delayed": true,
      "expression": "Block[{mu, ff}, Sum[-gw/(2*cw) Z[mu] NMbar.Ga[mu].ProjM.vl[ff] + HC[-gw/(2*cw) Z[mu] NMbar.Ga[mu].ProjM.vl[ff]], {ff, 1, 3}]]"
    },
    {
      "name": "LNH",
      "delayed": true,
      "expression": "Block[{ff}, Sum[-gw*mN/(2*MW)*H*(1 + gw/(4*MW)*H)*NMbar.ProjM.vl[ff] + HC[-gw*mN/(2*MW)*H*(1 + gw/(4*MW)*H)*NMbar.ProjM.vl[ff]], {ff, 1, 3}]]"
    },
    {
      "name": "LNGP",
      "delayed": true,
      "expression": "Block[{ff}, Sum[-I*gw*mN/(2*Sqrt[2]*MW)*GP*(1 + gw/(2*MW)*H)*(NMbar.ProjM.l[ff] + bar[CC[l[ff]]].ProjM.NM) + HC[-I*gw*mN/(2*Sqrt[2]*MW)*GP*(1 + gw/(2*MW)*H)*(NMbar.ProjM.l[ff] + bar[CC[l[ff]]].ProjM.NM)], {ff, 1, 3}]]"
    },
    {
      "name": "LNG0",
      "delayed": true,
      "expression": "Block[{ff}, Sum[-I*gw*mN/(2*MW)*G0*(1 + gw/(2*MW)*H)*NMbar.ProjM.vl[ff] + HC[-I*gw*mN/(2*MW)*G0*(1 + gw/(2*MW)*H)*NMbar.ProjM.vl[ff]], {ff, 1, 3}]]"
    },
    {
      "name": "LGG1",
      "delayed": true,
      "expression": "Block[{ff, ff2}, gw^2*mN/(8*MW^2)*(2*GP*GP*Sum[bar[CC[l[ff]]].ProjM.l[ff2], {ff, 1, 3}, {ff2, 1, 3}] + G0*G0*Sum[NMbar.ProjM.vl[ff], {ff, 1, 3}]) + HC[gw^2*mN/(8*MW^2)*(2*GP*GP*Sum[bar[CC[l[ff]]].ProjM.l[ff2], {ff, 1, 3}, {ff2, 1, 3}] + G0*G0*Sum[NMbar.ProjM.vl[ff], {ff, 1, 3}])]]"
    },
    {
      "name": "LGG2",
      "delayed": true,
      "expression": "Block[{ff}, gw^2*mN/(4*Sqrt[2]*MW^2)*G0*GP*Sum[NMbar.ProjM.l[ff] + bar[CC[l[ff]]].ProjM.NM, {ff, 1, 3}] + HC[gw^2*mN/(4*Sqrt[2]*MW^2)*G0*GP*Sum[NMbar.ProjM.l[ff] + bar[CC[l[ff]]].ProjM.NM, {ff, 1, 3}]]"
    },
    {
      "name": "LTotal",
      "delayed": true,
      "expression": "LNkin + LNW + LNZ + LNH + LNGP + LNG0 + LGG1 + LGG2"
    }
  ]
}
